1	/**
2	 * 事件引擎核心 — 随机事件判定、队列管理、弹窗 UI
3	 *
4	 * 拆分说明：事件数据已移至 events_street.js / events_corp.js
5	 * 这些文件在加载后自动推入 RANDOM_EVENTS 数组。
6	 */
7	
8	// ====== 空事件容器（由拆分文件在加载后推入）======
9	const RANDOM_EVENTS = [];
10	
11	/* =========================================================
12	 * 二、事件触发与队列管理
13	 * ========================================================= */
14	
15	/** 街头每日事件判定 */
16	function rollStreetEvent(state) {
17	  // 基础 18% 触发率，已存在待弹事件时不重复触发
18	  if (state._pendingEvent) return;
19	
20	  // 心理危机事件：mental<20时优先检查，不占用随机事件槽
21	  var mentalCrisisIds = [
22	    "mental_breakdown_edge",
23	    "mental_therapy_chance",
24	    "mental_recovery_milestone",
25	  ];
26	  for (var mci = 0; mci < mentalCrisisIds.length; mci++) {
27	    var mce = RANDOM_EVENTS.find(function (e) {
28	      return e.id === mentalCrisisIds[mci];
29	    });
30	    if (mce && typeof mce.conditions === "function" && mce.conditions(state)) {
31	      state._pendingEvent = mce;
32	      state.flags._todayMentalEvent = true;
33	      return;
34	    }
35	  }
36	
37	  // 村长债务追讨事件：债务未还时优先触发，不占用随机事件槽
38	  var debtEventIds = [
39	    "village_chief_warning",
40	    "village_chief_pressure",
41	    "village_chief_final",
42	  ];
43	  for (var dci = 0; dci < debtEventIds.length; dci++) {
44	    var dce = RANDOM_EVENTS.find(function (e) {
45	      return e.id === debtEventIds[dci];
46	    });
47	    if (dce && typeof dce.conditions === "function" && dce.conditions(state)) {
48	      state._pendingEvent = dce;
49	      state.flags._todayDebtEvent = true;
50	      return;
51	    }
52	  }
53	
54	  // 链式事件队列检查（高优先级，插入心理危机/债务检查之后，随机池之前）
55	  if (checkChainEventQueue(state, "street")) return;
56	
57	  const baseChance = 0.18;
58	  // 健康差或债务高时提高触发率
59	  let mod = 0;
60	  if (state.status.health < 50) mod += 0.1;
61	  if (state.resources.debt > 3000) mod += 0.05;
62	  if (state.needs.happiness < 30) mod += 0.05;
63	  // 历史声誉幸运加成（P2.9）：积善之人事件触发率降低
64	  if (typeof getHistoryModifiers === "function") {
65	    var lk = getHistoryModifiers(state).luckBonus || 0;
66	    mod -= lk * 0.008; // 每点幸运降低0.8%触发率（+5幸运≈-4%）
67	  }
68	  if (Math.random() < baseChance + mod) {
69	    queueRandomEvent(state, "street");
70	  }
71	}
72	
73	/** 职场每日事件判定 */
74	function rollCorporateEvent(state) {
75	  if (state._pendingEvent) return;
76	
77	  // 链式事件队列检查（高优先级）
78	  if (checkChainEventQueue(state, "corporate")) return;
79	
80	  const baseChance = 0.22;
81	  let mod = 0;
82	  if (state.player.corporate.risk > 50) mod += 0.1;
83	  if (state.player.corporate.popularity < 30) mod += 0.05;
84	  if (state.player.corporate.upwardMgmt < 20) mod += 0.05;
85	  if (Math.random() < baseChance + mod) {
86	    queueRandomEvent(state, "corporate");
87	  }
88	}
89	
90	/** 把一个随机事件塞进待弹队列 */
91	function queueRandomEvent(state, phase) {
92	  const pool = RANDOM_EVENTS.filter((e) => e.phase === phase);
93	  if (pool.length === 0) return;
94	
95	  // 过滤掉不满足条件的事件
96	  var eligible = pool.filter(function (e) {
97	    return !e.conditions || e.conditions(state);
98	  });
99	  if (eligible.length === 0) return;
100	
101	  // 新闻桥接加权：活跃新闻提升特定事件的触发权重
102	  var weights = eligible.map(function (e) {
103	    var w = 1.0;
104	    if (typeof getNewsBonusWeight === "function") {
105	      w += getNewsBonusWeight(e.id, state);
106	    }
107	    // 世界参数反馈环：行业热度高的领域相关事件更易触发
108	    if (typeof getSectorEventWeightMod === "function" && e.sector) {
109	      w *= getSectorEventWeightMod(e.sector);
110	    }
111	    return Math.max(0.1, w);
112	  });
113	  var totalWeight = weights.reduce(function (a, b) {
114	    return a + b;
115	  }, 0);
116	  var roll = Math.random() * totalWeight;
117	  var cursor = 0;
118	  var evt = eligible[0];
119	  for (var wi = 0; wi < eligible.length; wi++) {
120	    cursor += weights[wi];
121	    if (roll <= cursor) {
122	      evt = eligible[wi];
123	      break;
124	    }
125	  }
126	  // 使用唯一事件ID替代引用比较，避免引用失效导致事件卡住
127	  state._pendingEvent = evt;
128	  state._pendingEventId = evt.id;
129	  // 触发延迟到 render 阶段弹（避免在 tick 内部阻塞）
130	  setTimeout(() => {
131	    const s = StateManager.getState();
132	    if (s._pendingEvent && s._pendingEventId === evt.id) {
133	      showEventModal(evt);
134	      if (typeof playSound === "function") playSound("event");
135	      // 不再自动关闭——玩家必须手动点击选择（游戏设计决定）
136	    }
137	  }, 50);
138	}
139	
140	/* =========================================================
141	 * 三、事件弹窗 UI
142	 * ========================================================= */
143	
144	/**
145	 * 渲染并展示一个事件模态框
146	 * @param {Object} evt - 事件对象
147	 */
148	function showEventModal(evt) {
149	  // 先卸掉任何旧弹窗
150	  document.querySelector(".modal-overlay")?.remove();
151	
152	  // 支持 choices 为函数（动态生成，如政策套利兑现事件）
153	  var choicesArr = evt.choices;
154	  if (typeof choicesArr === "function") {
155	    choicesArr = choicesArr(StateManager.getState());
156	    if (!choicesArr || !choicesArr.length) {
157	      // 没有可用选项时自动跳过
158	      var s = StateManager.getState();
159	      s._pendingEvent = null;
160	      s._pendingEventId = null;
161	      return;
162	    }
163	  }
164	
165	  // ====== 春节事件专属检测 ======
166	  var isSpringFest = !!evt._isSpringFestivalEvent;
167	  var springFestClass = isSpringFest ? "spring-fest-modal" : "";
168	  var springFestProgressHtml = "";
169	  var springFestDecorHtml = "";
170	
171	  if (isSpringFest) {
172	    // 进度指示器：春节7天（除夕→初六）
173	    var dayNames = ["除夕", "初一", "初二", "初三", "初四", "初五", "初六"];
174	    var dayIcons = ["🏠", "🧧", "👨‍👩‍👧", "🔴", "💰", "🔨", "🗑️"];
175	    var currentDay = evt.id
176	      ? parseInt(evt.id.replace("spring_fest_day", ""))
177	      : 0;
178	    currentDay = Math.max(0, Math.min(6, currentDay));
179	
180	    var dotsHtml = "";
181	    for (var d = 0; d < 7; d++) {
182	      var dotClass = "spring-fest-progress-dot";
183	      if (d === currentDay) dotClass += " active";
184	      else if (d < currentDay) dotClass += " passed";
185	      dotsHtml += '<div class="' + dotClass + '"></div>';
186	    }
187	
188	    springFestProgressHtml =
189	      '<div class="spring-fest-progress">' +
190	      '<span class="spring-fest-progress-label">🧨 春节</span>' +
191	      '<div class="spring-fest-progress-dots">' +
192	      dotsHtml +
193	      "</div>" +
194	      '<span class="spring-fest-progress-label" style="margin-left:4px;">第' +
195	      (currentDay + 1) +
196	      "/7天 · " +
197	      dayNames[currentDay] +
198	      "</span>" +
199	      "</div>";
200	
201	    // 春节装饰元素
202	    springFestDecorHtml =
203	      '<span class="spring-fest-decor lantern-left">🏮</span>' +
204	      '<span class="spring-fest-decor lantern-right">🏮</span>' +
205	      '<span class="spring-fest-decor coin-bottom">💰</span>';
206	  }
207	
208	  // 构建选项HTML
209	  const choicesHtml = choicesArr
210	    .map((ch, i) => {
211	      const hintStr = ch.hint
212	        ? `<div class="choice-hint">${ch.hint}</div>`
213	        : "";
214	      // 检查现金是否够
215	      let disabled = false;
216	      if (ch.cost && StateManager.getState().resources.cash < ch.cost) {
217	        disabled = true;
218	      }
219	      const costTag = ch.cost
220	        ? ` <span style="color:var(--warning);font-size:11px;">需 ¥${ch.cost}</span>`
221	        : "";
222	      return `
223	        <button class="event-choice ${disabled ? "disabled" : ""}" data-idx="${i}" ${disabled ? "disabled" : ""}>
224	          <div class="choice-main">${ch.text}${costTag}</div>
225	          ${hintStr}
226	        </button>
227	      `;
228	    })
229	    .join("");
230	
231	  const overlay = document.createElement("div");
232	  overlay.className = "modal-overlay event-modal " + springFestClass;
233	  overlay.innerHTML = `
234	    <div class="modal-box event-box ${springFestClass}">
235	      ${springFestDecorHtml}
236	      ${springFestProgressHtml}
237	      <div class="event-header">
238	        <div class="event-icon">${evt.icon}</div>
239	        <h2 class="event-title">${evt.title}</h2>
240	      </div>
241	      <p class="event-story ${isSpringFest ? "spring-fest-story" : ""}">${evt.story}</p>
242	      <div class="event-choices">${choicesHtml}</div>
243	      <div style="text-align:center;margin-top:8px;font-size:10px;color:var(--accent);">
244	        ${isSpringFest ? "🧨 做出你的选择，迎接新的一年" : "⚡ 请选择一个选项继续"}
245	      </div>
246	    </div>
247	  `;
248	  document.body.appendChild(overlay);
249	
250	  // 绑定选项点击
251	  overlay.querySelectorAll(".event-choice").forEach((btn) => {
252	    btn.addEventListener("click", () => {
253	      const idx = parseInt(btn.dataset.idx);
254	      const choice = choicesArr[idx];
255	      if (!choice) return;
256	      const state = StateManager.getState();
257	      try {
258	        if (typeof choice.apply === "function") {
259	          choice.apply(state);
260	          // NPC事件桥接：事件结算后自动触发NPC好感变化
261	          if (typeof afterEventApplied === "function") {
262	            afterEventApplied(evt.id, state);
263	          }
264	        } else if (typeof choice.effect === "function") {
265	          // 兼容春节活动事件的 effect 模式（返回 {ok, msg}）
266	          var result = choice.effect(state);
267	          if (result && result.ok === false) {
268	            // 效果失败（如钱不够），不关闭弹窗
269	            return;
270	          }
271	        }
272	      } catch (e) {
273	        console.error("Event choice apply error:", e);
274	      }
275	      // 清掉待弹事件（三字段全部清理）
276	      state._pendingEvent = null;
277	      state._pendingEventId = null;
278	      // 关闭弹窗 + 重新渲染
279	      document.body.removeChild(overlay);
280	      renderAll();
281	    });
282	  });
283	
284	  // 点击遮罩关闭也清理事件悬挂
285	  overlay.addEventListener("click", (e) => {
286	    if (e.target === overlay) {
287	      const s = StateManager.getState();
288	      s._pendingEvent = null;
289	      s._pendingEventId = null;
290	      document.body.removeChild(overlay);
291	      renderAll();
292	    }
293	  });
294	}
