296	/** 跳槽 offer 决策弹窗（被 corp_headhunter 事件调用） */
297	function showJobOfferModal() {
298	  const state = StateManager.getState();
299	  const offer = state.corporate.jobOffer;
300	  if (!offer) return;
301	  showModal({
302	    title: "💼 跳槽 Offer 决策",
303	    body: `
304	      <p>另一家公司开出了 <strong style="color:var(--success);">年薪 ¥${offer.salary.toLocaleString()}</strong> 的条件挖你！</p>
305	      <p style="font-size:12px;color:var(--text-secondary);">跳槽有风险：人缘归零、向上管理归零、KPI 减半、需重新建立关系。</p>
306	    `,
307	    buttons: [
308	      { text: "继续考虑", cls: "", callback: () => {} },
309	      {
310	        text: `接受 Offer (¥${offer.salary.toLocaleString()})`,
311	        cls: "btn-success",
312	        callback: () => {
313	          // 简化版：直接加钱 + 重置属性
314	          state.resources.cash += offer.salary;
315	          state.player.corporate.kpi = Math.max(
316	            0,
317	            state.player.corporate.kpi * 0.5,
318	          );
319	          state.player.corporate.popularity = Math.max(
320	            0,
321	            state.player.corporate.popularity - 30,
322	          );
323	          state.player.corporate.upwardMgmt = Math.max(
324	            0,
325	            state.player.corporate.upwardMgmt - 30,
326	          );
327	          state.corporate.jobOffer = null;
328	          StateManager.addMessage(
329	            `💼 接受了新公司的 offer，拿到 ¥${offer.salary.toLocaleString()} 签字费！`,
330	            "event",
331	          );
332	          renderAll();
333	        },
334	      },
335	    ],
336	  });
337	}
338	
339	/* =========================================================
340	 * 三·五、链式事件调度管理
341	 * ========================================================= */
342	
343	/**
344	 * 调度一个链式事件在 delayDays 后触发
345	 * @param {Object} state - 游戏状态
346	 * @param {string} eventId - 事件ID
347	 * @param {number} delayDays - 延迟天数
348	 * @param {string} phase - "street" | "corporate"
349	 */
350	function scheduleChainEvent(state, eventId, delayDays, phase) {
351	  if (!state.flags._chainEventQueue) {
352	    state.flags._chainEventQueue = [];
353	  }
354	  var triggerDay = state.player.day + delayDays;
355	  // 避免重复调度同一事件
356	  for (var i = 0; i < state.flags._chainEventQueue.length; i++) {
357	    if (state.flags._chainEventQueue[i].eventId === eventId) {
358	      state.flags._chainEventQueue[i].triggerDay = triggerDay;
359	      return;
360	    }
361	  }
362	  state.flags._chainEventQueue.push({
363	    eventId: eventId,
364	    triggerDay: triggerDay,
365	    phase: phase,
366	  });
367	}
368	
369	/**
370	 * 检查链式事件队列，有到期事件时直接弹出
371	 * @param {Object} state - 游戏状态
372	 * @param {string} phase - "street" | "corporate"
373	 * @returns {boolean} 是否触发了链式事件
374	 */
375	function checkChainEventQueue(state, phase) {
376	  if (state._pendingEvent) return false;
377	  var queue = state.flags._chainEventQueue;
378	  if (!queue || queue.length === 0) return false;
379	
380	  // 按触发日排序，最急的在前
381	  queue.sort(function (a, b) {
382	    return a.triggerDay - b.triggerDay;
383	  });
384	
385	  for (var i = 0; i < queue.length; i++) {
386	    var entry = queue[i];
387	    if (entry.phase !== phase) continue;
388	    if (state.player.day < entry.triggerDay) continue;
389	
390	    // 从队列移除该事件
391	    queue.splice(i, 1);
392	
393	    // 在 RANDOM_EVENTS 中查找对应事件
394	    for (var j = 0; j < RANDOM_EVENTS.length; j++) {
395	      if (RANDOM_EVENTS[j].id === entry.eventId) {
396	        state._pendingEvent = RANDOM_EVENTS[j];
397	        state._pendingEventId = entry.eventId;
398	        // 延迟弹窗（避免在 tick 内部阻塞）
399	        setTimeout(
400	          (function (evt) {
401	            return function () {
402	              var s = StateManager.getState();
403	              if (s._pendingEvent && s._pendingEventId === evt.id) {
404	                showEventModal(evt);
405	                if (typeof playSound === "function") playSound("event");
406	              }
407	            };
408	          })(RANDOM_EVENTS[j]),
409	          80,
410	        );
411	        return true;
412	      }
413	    }
414	    // 没找到事件（可能被删了），继续检查下一条
415	  }
416	  return false;
417	}
418	
419	/* =========================================================
420	 * 四、兼容旧 API
421	 * ========================================================= */
422	
423	/** 每日新闻判定（旧 API，保持兼容） */
424	function rollDailyNews(state) {
425	  // 街头阶段：触发随机事件弹窗，同时小概率触发投资新闻
426	  if (state.player.phase === "street") {
427	    rollStreetEvent(state);
428	    // 8%概率接到市场消息（影响投资市场，仅投资类新闻）
429	    if (Math.random() < 0.08 && typeof getRandomNewsEvent === "function") {
430	      var investNews = null;
431	      for (var _attempt = 0; _attempt < 5; _attempt++) {
432	        var candidate = getRandomNewsEvent();
433	        if (
434	          candidate &&
435	          candidate.type === "investment" &&
436	          !(state.flags.seenNewsToday || []).includes(candidate.id)
437	        ) {
438	          investNews = candidate;
439	          break;
440	        }
441	      }
442	      if (investNews) {
443	        investNews._appliedDay = state.player.day;
444	        state.activeNews = state.activeNews || [];
445	        state.activeNews.push(investNews);
446	        state.flags.seenNewsToday = state.flags.seenNewsToday || [];
447	        state.flags.seenNewsToday.push(investNews.id);
448	        applyNewsEffect(investNews, state);
449	        StateManager.addMessage("📰 " + investNews.headline, "event");
450	      }
451	    }
452	    return;
453	  }
454	  // 职场阶段：保留少量市场新闻 + 事件弹窗
455	  const newsChance = state.activeNews.length > 0 ? 0.05 : 0.12;
456	  if (Math.random() < newsChance) {
457	    const news = getRandomNewsEvent();
458	    if (news && !state.flags.seenNewsToday.includes(news.id)) {
459	      news._appliedDay = state.player.day;
460	      state.activeNews.push(news);
461	      state.flags.seenNewsToday.push(news.id);
462	      applyNewsEffect(news, state);
463	      StateManager.addMessage(`📰 ${news.headline}`, "event");
464	    }
465	  }
466	  // 职场事件
467	  rollCorporateEvent(state);
468	  // 清理今日已见新闻列表
469	  if (state.player.day % 3 === 0) {
470	    state.flags.seenNewsToday = [];
471	  }
472	}
473	
474	/** 每日结束时的清理 */
475	function dailyCleanup(state) {
476	  cleanupExpiredNews(state);
477	  // 清理链式事件队列中已过期的条目
478	  if (state.flags._chainEventQueue && state.flags._chainEventQueue.length > 0) {
479	    state.flags._chainEventQueue = state.flags._chainEventQueue.filter(
480	      function (entry) {
481	        return state.player.day < entry.triggerDay + 30;
482	      },
483	    );
484	  }
485	  // 清理 L1-L4 新闻传导队列
486	  if (typeof cleanupConduitQueue === "function") {
487	    cleanupConduitQueue(state);
488	  }
489	}
490	
491	/** 季度结束时的职场清理 */
492	function quarterlyCleanup(state) {
493	  // 占位（兼容旧调用）
494	}
